def get_section_display_name(sec) -> str:
    """获取截面的显示名称
    
    规则：
    - 如果名称已包含类型前缀（如 RHS300x200x8），则去掉名称中的前缀，格式化为 "RHS 300x200x8"
    - 如果名称不含类型前缀（如 UB 的 "457x191x82"），则添加前缀，格式化为 "UB 457x191x82"
    """
    # 如果名称已以类型开头（如 CHS273x10、SHS200x200x8、RHS300x200x8）
    if sec.name.startswith(sec.type):
        # 去掉名称中的类型前缀，保留尺寸部分
        dimensions = sec.name[len(sec.type):]
        # 如果尺寸部分以数字开头，添加空格
        if dimensions and dimensions[0].isdigit():
            return f"{sec.type} {dimensions}"
        else:
            # 尺寸部分可能直接是类型名（如 "CHS" 情况下会走到这里，但理论上不会发生）
            return sec.name
    else:
        # 名称不含类型前缀，直接添加前缀
        return f"{sec.type} {sec.name}"


