    chat_container = st.container()
    with chat_container:
        for msg in st.session_state["ai_messages"]:
            if msg["role"] == "user":
                st.chat_message("user").write(msg["content"])
            else:
                st.chat_message("assistant").write(msg["content"])
    
    # 处理反问后的用户回复（用户确认截面选型）
