def _is_confirmation(prompt: str) -> bool:
    """检测用户是否确认继续截面选型"""
    confirm_keywords = ["需要", "是", "要", "好", "继续", "可以", "开始", "进行", "选型", "确定"]
    deny_keywords = ["不需要", "否", "不用", "不用了", "不了", "取消", "结束", "不用选", "不用了"]
    
    prompt_lower = prompt.lower().strip()
    
    # 先检查是否明确拒绝
    for keyword in deny_keywords:
        if keyword in prompt_lower:
            return False
    
    # 检查是否确认
    for keyword in confirm_keywords:
        if keyword in prompt_lower:
            return True
    
    return False


def _parse_section_type(prompt: str) -> str:
    """解析用户输入的截面类型"""
    prompt_lower = prompt.lower().strip()
    
    # 截面类型关键词映射
    type_mapping = {
        # UB - 工字钢
        "ub": "UB",
        "工字钢": "UB",
        "工字形": "UB",
        "i字钢": "UB",
        "i型钢": "UB",
        "普通工字钢": "UB",
        "梁": "UB",
        
        # UC - H型钢
        "uc": "UC",
        "h型钢": "UC",
        "h型": "UC",
        "h钢": "UC",
        "宽翼缘": "UC",
        "柱": "UC",
        "hw": "UC",
        "hm": "UC",
        
        # PFC - 槽钢
        "pfc": "PFC",
        "槽钢": "PFC",
        "c型钢": "PFC",
        
        # CHS - 圆管
        "chs": "CHS",
        "圆管": "CHS",
        "圆形管": "CHS",
        "圆钢管": "CHS",
        "圆": "CHS",
        
        # SHS - 方管
        "shs": "SHS",
        "方管": "SHS",
        "方形管": "SHS",
        "方形": "SHS",
        "方": "SHS",
        
        # RHS - 矩形管
        "rhs": "RHS",
        "矩形管": "RHS",
        "长方形管": "RHS",
        "矩形": "RHS",
        
        # EA - 角钢
        "ea": "EA",
        "角钢": "EA",
        "等边角钢": "EA",
        "l型": "EA",
        "l型钢": "EA",
    }
    
    # 遍历映射表查找匹配
    for keyword, section_type in type_mapping.items():
        if keyword in prompt_lower:
            return section_type
    
    # 如果直接输入UB/UC等代码
    valid_types = ["UB", "UC", "PFC", "CHS", "SHS", "RHS", "EA"]
    prompt_upper = prompt.upper().strip()
    if prompt_upper in valid_types:
        return prompt_upper
    
    return ""


def _get_section_type_name(section_type: str) -> str:
    """获取截面类型的中文名称"""
    type_names = {
        "UB": "UB (通用梁/工字钢)",
        "UC": "UC (通用柱/H型钢)",
        "PFC": "PFC (槽钢)",
        "CHS": "CHS (圆管)",
        "SHS": "SHS (方管)",
        "RHS": "RHS (矩形管)",
        "EA": "EA (等边角钢)",
    }
    return type_names.get(section_type, section_type)


def _perform_section_selection(requested_section_type: str = None):
    """执行截面选型（用户确认后调用）
    
    Args:
        requested_section_type: 用户指定的截面类型，如果不指定则使用默认或session中保存的类型
    """
    parsed = st.session_state.get("parsed_params", {})
    struct_type = st.session_state.get("structure_type", "continuous_beam")
    best = None  # 初始化 best 变量，避免后续引用错误
    
    with st.chat_message("assistant"):
        st.markdown("---")
        st.markdown("#### 📊 截面选型结果")
        
        with st.spinner("正在为您进行截面选型..."):
            # 截面选型
            prefer_inventory = st.session_state.get("prefer_inventory", True)
            
            # 确定要使用的截面类型
            if requested_section_type is None:
                requested_section_type = st.session_state.get("selected_section_type", None)
            
            # 如果用户指定了截面类型，只搜索该类型
            if requested_section_type:
                section_types = [requested_section_type]
                type_display = _get_section_type_name(requested_section_type)
                st.markdown(f"**筛选条件：** 截面类型 = {type_display}")
            else:
                section_types = st.session_state.get("section_types", ["UB"])
                type_display = "全部类型"
            
            # 根据结构类型选择不同的选型函数
            if struct_type == "continuous_beam":
                # 连续梁：使用连续梁选型函数
                spans = st.session_state.get("spans", [])
                calc_result = st.session_state.get("calc_result", {})
                
                if not spans or not calc_result:
                    st.error("未找到计算结果，请重新输入设计需求")
                    return
                
                results, cost_best, util_best = select_sections_for_continuous_beam(
                    spans,
                    calc_result["max_M"],
                    calc_result["max_V"],
                    section_types,
                    prefer_inventory
                )
                df_columns = ["截面", "利用率", "成本(元)", "总质量(kg)", "库存(m)"]
                is_continuous = True
            else:
                # 简支梁、悬臂梁、固端梁：使用单跨梁选型函数
                pending_params = st.session_state.get("pending_simple_beam_params", {})
                
                if not pending_params:
                    st.error("未找到计算结果，请重新输入设计需求")
                    return
                
                span = pending_params["span"]
                M = pending_params["M"]
                V = pending_params["V"]
                
                results = select_sections("beam", span, M, V, 0, "利用率", section_types, prefer_inventory)
                df_columns = ["截面", "利用率", "成本(元)", "质量(kg/m)", "库存(m)"]
                # 非连续梁：设置默认值
                cost_best, util_best = {}, {}
                is_continuous = False
        
        if results:
            st.session_state["results"] = results
            st.session_state["best_section"] = results[0]
        
            df = pd.DataFrame(results)
            df_display = df[df_columns]
            st.dataframe(df_display, use_container_width=True, hide_index=True)
        
            # 连续梁显示双推荐卡片
            if is_continuous and cost_best and util_best:
                is_same = cost_best['截面'] == util_best['截面']
                
                col1, col2 = st.columns(2)
                
                with col1:
                    st.success(f"""
                    **💸 成本最优推荐**
                    
                    截面：**{cost_best['截面']}**
                    类型：{cost_best['类型']} | 利用率：{cost_best['利用率']} | 成本：{cost_best['成本(元)']}元 | 库存：{cost_best['库存(m)']}
                    """)
                
                with col2:
                    if not is_same:
                        st.info(f"""
                        **📊 利用率最优推荐**
                        
                        截面：**{util_best['截面']}**
                        类型：{util_best['类型']} | 利用率：{util_best['利用率']} | 成本：{util_best['成本(元)']}元 | 库存：{util_best['库存(m)']}
                        """)
                    else:
                        st.info(f"""
                        **📊 利用率最优推荐**
                        
                        （与成本最优相同）
                        截面：**{util_best['截面']}**
                        类型：{util_best['类型']} | 利用率：{util_best['利用率']} | 成本：{util_best['成本(元)']}元 | 库存：{util_best['库存(m)']}
                        """)
                
                # 使用成本最优作为默认推荐用于AI解读
                best = cost_best
            else:
                # 非连续梁直接使用第一个结果
                best = results[0] if results else None
            
            if best:
                recommendation = generate_recommendation(parsed, best, struct_type)
                st.info(f"**💬 AI解读：** {recommendation}")
                st.session_state["ai_recommendation"] = recommendation
                
                if requested_section_type:
                    response = f"✅ 选型完成！基于您选择的 **{_get_section_type_name(requested_section_type)}**，推荐截面 **{best['截面']}**，利用率 **{best['利用率']}**，成本 **{best['成本(元)']}元**"
                else:
                    response = f"✅ 选型完成！推荐截面 **{best['截面']}**，利用率 **{best['利用率']}**，成本 **{best['成本(元)']}元**"
                st.session_state["ai_messages"].append({"role": "assistant", "content": response})
            
            # 重置截面类型选择状态
            st.session_state["selected_section_type"] = None
        else:
            no_result_msg = f"""没有找到符合条件的 **{_get_section_type_name(requested_section_type) if requested_section_type else '所选'}** 截面。

可能的原因：
1. 该类型截面的承载力不足
2. 该类型截面库存为零

您可以尝试：
- 选择其他截面类型（如UB、UC等）
- 调整结构参数
- 返回重新输入设计需求"""
            st.warning(no_result_msg)
            st.session_state["ai_messages"].append({"role": "assistant", "content": no_result_msg})

