    COST_DB = _get_cost_db()
    INVENTORY_DB = _get_inventory_db()
    
    # 标题栏：左侧标题，右侧三行按钮
    title_col, right_btn_col = st.columns([4, 1])
    with title_col:
        st.markdown("""<h2 style="color:#FFFFFF;font-family:'Microsoft YaHei','SimHei',sans-serif;font-weight:900;font-size:60px;letter-spacing:1px;margin:0;padding:0;line-height:1.2;">工料测量模块</h2>""", unsafe_allow_html=True)
    with right_btn_col:
        if st.button("← 返回主界面", key="btn_back_cost", use_container_width=True, type="secondary"):
            st.session_state["current_page"] = "main"
            st.rerun()
        if st.button("⚙️ 管理员", key="btn_admin_cost", use_container_width=True, type="secondary"):
            st.session_state["current_page"] = "admin"
            st.rerun()
        if st.button("退出登录", key="btn_logout_cost", use_container_width=True, type="secondary"):
            st.session_state["logged_in"] = False
            st.session_state["ai_messages"] = []
            st.rerun()
    
    st.markdown("---")
    
    # 毛玻璃卡片效果容器
    st.markdown("""
    <style>
    .glass-card {
        background: rgba(10, 25, 60, 0.7);
        backdrop-filter: blur(15px);
        border: 1px solid rgba(0, 180, 255, 0.3);
        border-radius: 16px;
        padding: 25px;
        margin: 10px 0;
        box-shadow: 0 8px 32px rgba(0, 0, 0, 0.3);
    }
    .section-title {
        color: #00b4ff;
        font-size: 1.3em;
        font-weight: bold;
        margin-bottom: 15px;
        border-bottom: 2px solid rgba(0, 180, 255, 0.3);
        padding-bottom: 10px;
    }
    </style>
    """, unsafe_allow_html=True)
    
    # 功能选择标签页
    data_tabs = st.tabs(["💰 成本库", "📊 造价估算", "📐 工程量统计"])
    
    # 成本库
    with data_tabs[0]:
        st.markdown('<div class="glass-card">', unsafe_allow_html=True)
        st.markdown('<div class="section-title">💰 成本库管理</div>', unsafe_allow_html=True)
        
        # 显示当前成本库
        st.markdown("##### 当前成本库单价")
        cost_data = []
        for sec in SECTIONS_DB:
            price = COST_DB.get(sec.name, 4.0)
            cost_data.append({
                "截面名称": get_section_display_name(sec),
                "单价(元/kg)": price,
                "单位质量(kg/m)": sec.mass
            })
        
        df_cost = pd.DataFrame(cost_data)
        st.dataframe(df_cost, use_container_width=True, hide_index=True, height=350)
        st.caption(f"共 {len(cost_data)} 个截面规格")
        
        st.markdown("---")
        
        # 成本库更新
        st.markdown("##### 🤖 AI更新成本库")
        st.markdown("例如：`将UB类单价调整为4.8元` 或 `456x191x82单价设为5.0元`")
        
        cost_input = st.text_area("输入成本更新指令", key="cost_ai_input", height=80, placeholder="请输入成本更新指令...")
        
        col1, col2 = st.columns(2)
        with col1:
            if st.button("🔧 执行成本库更新", key="btn_cost_update", use_container_width=True, type="secondary"):
                if cost_input.strip():
                    with st.spinner("AI解析中..."):
                        try:
                            update_result = parse_cost_update(cost_input)
                            if update_result:
                                st.success(f"✅ 成本库更新成功！{update_result}")
                                st.rerun()
                            else:
                                st.warning("⚠️ 未能解析出有效的成本数据，请检查输入格式")
                        except Exception as e:
                            st.error(f"❌ 更新失败：{e}")
                else:
                    st.warning("请输入更新指令")
        
        with col2:
            if st.button("🔄 重置为默认", key="btn_cost_reset", use_container_width=True, type="secondary"):
                st.session_state["COST_DB"] = dict(_DEFAULT_COST_DB)
                st.success("✅ 已重置为默认成本库！")
                st.rerun()
        
        st.markdown('</div>', unsafe_allow_html=True)
    
    # 造价估算
    with data_tabs[1]:
        st.markdown('<div class="glass-card">', unsafe_allow_html=True)
        st.markdown('<div class="section-title">📊 造价估算</div>', unsafe_allow_html=True)
        
        # 截面选择
        section_options = [s.name for s in SECTIONS_DB]
        selected_section = st.selectbox("选择截面", section_options, key="cost_section_select")
        
        # 获取截面信息
        sec = next((s for s in SECTIONS_DB if s.name == selected_section), None)
        if sec:
            col1, col2, col3, col4 = st.columns(4)
            with col1:
                st.metric("截面名称", sec.name)
            with col2:
                st.metric("截面类型", sec.type)
            with col3:
                st.metric("单位质量", f"{sec.mass:.1f} kg/m")
            with col4:
                unit_price = COST_DB.get(sec.name, 4.0)
                st.metric("单价", f"{unit_price:.2f} 元/kg")
        
        # 长度输入
        length = st.number_input("构件长度 (m)", 0.5, 50.0, 6.0, 0.5, key="cost_length_input")
        
        # 计算造价
        if sec:
            total_mass = sec.mass * length
            total_cost = total_mass * COST_DB.get(sec.name, 4.0)
            
            st.markdown("---")
            st.markdown("##### 📋 造价估算结果")
            
            result_col1, result_col2, result_col3 = st.columns(3)
            with result_col1:
                st.metric("总质量", f"{total_mass:.2f} kg")
            with result_col2:
                st.metric("预估造价", f"¥{total_cost:.2f}")
            with result_col3:
                st.metric("截面面积", f"{sec.A:.1f} cm²")
        
        st.markdown('</div>', unsafe_allow_html=True)
    
    # 工程量统计
    with data_tabs[2]:
        st.markdown('<div class="glass-card">', unsafe_allow_html=True)
        st.markdown('<div class="section-title">📐 工程量统计</div>', unsafe_allow_html=True)
        
        st.info("功能开发中，敬请期待...")
        
        st.markdown('</div>', unsafe_allow_html=True)


