def parse_template_natural_language(user_input: str) -> Optional[Dict[str, Any]]:
    """调用 DeepSeek API 解析模板设计的自然语言描述"""
    template_system_prompt = """你是一个混凝土模板设计助手，专门解析模板设计任务描述并返回JSON参数。

判断标准：
- 是设计任务：用户描述了模板类型、混凝土参数、施工参数等
- 不是设计任务：用户在闲聊或询问非设计问题

当用户不是在描述具体设计任务时，返回 None。

支持的模板类型：
- 墙/柱模板
- 梁模板
- 板模板

支持的材料：
- 面板材料：胶合板 (15mm)、胶合板 (18mm)、钢模板
- 木楞材料：方木 (50x80mm)、方木 (60x80mm)、方木 (80x100mm)、工字钢

参数范围：
- 混凝土厚度：100-2000 mm
- 浇筑高度：1-10 m
- 木楞间距：200-600 mm
- 支撑间距：500-1500 mm
- 支撑高度：1-10 m
- 恒载分项系数：1.0-1.5
- 活载分项系数：1.0-2.0

示例：
- "墙模板，混凝土厚度300mm，浇筑高度3m" → {"template_type": "墙/柱模板", "concrete_thickness": 300, "pour_height": 3.0, "purlin_spacing": 300, "support_spacing": 1000, "panel_material": "胶合板 (18mm)", "purlin_material": "方木 (60x80mm)", "support_height": 3.0}
- "梁模板，胶合板18mm，木楞60x80mm" → {"template_type": "梁模板", "concrete_thickness": 300, "pour_height": 3.0, "purlin_spacing": 300, "support_spacing": 1000, "panel_material": "胶合板 (18mm)", "purlin_material": "方木 (60x80mm)", "support_height": 3.0}
- "板模板，混凝土厚度150mm，支撑间距1m" → {"template_type": "板模板", "concrete_thickness": 150, "pour_height": 3.0, "purlin_spacing": 300, "support_spacing": 1000, "panel_material": "胶合板 (18mm)", "purlin_material": "方木 (60x80mm)", "support_height": 3.0}

只返回JSON，不要其他文字。如果无法解析，返回 null。"""
    
    try:
        client = get_deepseek_client()
        response = client.chat.completions.create(
            model=DEEPSEEK_MODEL,
            messages=[
                {"role": "system", "content": template_system_prompt},
                {"role": "user", "content": user_input}
            ],
            temperature=0.1,
        )
        
        result_text = response.choices[0].message.content.strip()
        
        # 提取 JSON
        json_match = re.search(r'\{.*\}', result_text, re.DOTALL)
        if json_match:
            parsed = json.loads(json_match.group())
            return parsed
        return None
    except Exception as e:
        return None

def calculate_template_loads(concrete_thickness, pour_height, gamma_g, gamma_q, template_type):
    """计算模板荷载"""
    concrete_self = 24 * concrete_thickness / 1000
    construction_load = 1.0
    vibration_load = 2.0
    lateral_pressure = 0
    if template_type == "墙/柱模板":
        lateral_pressure = min(25 * pour_height, 72)
        total_load = gamma_g * (concrete_self + lateral_pressure) + gamma_q * (construction_load + vibration_load)
    else:
        total_load = gamma_g * concrete_self + gamma_q * (construction_load + vibration_load)
    
    return {
        'concrete_self': concrete_self,
        'construction_load': construction_load,
        'vibration_load': vibration_load,
        'lateral_pressure': lateral_pressure,
        'total_load': total_load,
        'template_type': template_type,
        'pour_height': pour_height
    }


def calculate_panel_internal_forces(q, span, thickness, material):
    """面板内力计算 - 按多跨连续梁计算（每米宽度）"""
    L = span / 1000
    q_N_mm = q * 1
    
    M1 = 0.078 * q_N_mm * L * L * 1000
    M2 = 0.033 * q_N_mm * L * L * 1000
    M_B = 0.105 * q_N_mm * L * L * 1000
    M_max = max(M1, M2, abs(M_B))
    
    V_max = 0.606 * q_N_mm * L * 1000
    
    E = 9000 if "胶合板" in material else 206000
    I = thickness ** 3 / 12
    deflection = 0.0067 * q_N_mm * L ** 4 / (E * I) * 1000
    
    return {
        'M_max': M_max,
        'M1': M1,
        'M2': M2,
        'M_B': M_B,
        'V_max': V_max,
        'deflection': deflection,
        'span': span,
        'E': E,
        'I': I
    }


def calculate_purlin_internal_forces(q, purlin_spacing, support_spacing, b, h):
    """木楞内力计算 - 按多跨连续梁计算"""
    L = support_spacing / 1000
    q_line = q * purlin_spacing / 1000
    
    M1 = 0.078 * q_line * L * L
    M2 = 0.033 * q_line * L * L
    M_B = 0.105 * q_line * L * L
    M_max = max(M1, M2, abs(M_B))
    
    V_max = 0.606 * q_line * L
    
    E = 9000
    I = b * h ** 3 / 12
    deflection = 0.0067 * q_line * L ** 4 / (E * I) * 1000
    
    return {
        'M_max': M_max,
        'V_max': V_max,
        'deflection': deflection,
        'span': support_spacing,
        'b': b,
        'h': h,
        'E': E,
        'I': I
    }


def calculate_support_internal_forces(q, support_spacing, height, fc, A, i):
    """支撑轴力计算 - 轴压构件"""
    N = q * support_spacing * support_spacing / 1000
    
    return {
        'N': N,
        'height': height,
        'A': A,
        'i': i
    }


def check_panel_section(panel, thickness, E, fm):
    """面板截面验算"""
    W = thickness ** 2 / 6
    M_n = fm * W * 1000
    M_util = panel['M_max'] / M_n
    
    t = thickness
    V_n = fm / 1.5 * t * thickness / 1.5
    V_util = panel['V_max'] / V_n if V_n > 0 else 0
    
    L = panel['span'] / 1000
    allow_defl = L * 1000 / 400
    defl_util = panel['deflection'] / allow_defl
    
    util = max(M_util, V_util, defl_util)
    ok = util < 1.0
    
    return {
        'M_util': M_util,
        'V_util': V_util,
        'defl_util': defl_util,
        'util': util,
        'ok': ok,
        'M_n': M_n,
        'V_n': V_n,
        'allow_defl': allow_defl
    }


def check_purlin_section(purlin, b, h, E, fm, fv):
    """木楞截面验算"""
    Wx = b * h ** 2 / 6
    M_n = fm * Wx * 1000
    M_util = purlin['M_max'] / M_n
    
    V_n = fv * b * h * 1000
    V_util = purlin['V_max'] / V_n if V_n > 0 else 0
    
    L = purlin['span'] / 1000
    allow_defl = L * 1000 / 400
    defl_util = purlin['deflection'] / allow_defl
    
    util = max(M_util, V_util, defl_util)
    ok = util < 1.0
    
    return {
        'M_util': M_util,
        'V_util': V_util,
        'defl_util': defl_util,
        'util': util,
        'ok': ok,
        'M_n': M_n,
        'V_n': V_n,
        'allow_defl': allow_defl
    }


def check_support_section(support, fc, A, height, i):
    """支撑截面验算"""
    lambda_ = height * 1000 / i
    if lambda_ <= 20:
        phi = 1.0
    elif lambda_ <= 30:
        phi = 1.0 - 0.63 * (lambda_ - 20) / 30
    else:
        phi = 2900 / (lambda_ ** 2)
    
    N_n = phi * fc * A
    util = support['N'] / N_n if N_n > 0 else 1.0
    ok = util < 1.0 and lambda_ < 200
    
    return {
        'phi': phi,
        'N_n': N_n,
        'util': util,
        'ok': ok,
        'lambda': lambda_
    }


def generate_template_calc_sheet(params, result):
    """生成模板计算书"""
    loads = result['loads']
    panel = result['panel']
    purlin = result['purlin']
    support = result['support']
    panel_check = result['panel_check']
    purlin_check = result['purlin_check']
    support_check = result['support_check']
    
    today = datetime.now().strftime("%Y-%m-%d")
    lateral_row = f"| 侧压力 | {loads['lateral_pressure']:.2f} | kN/m² |" if params['template_type'] == '墙/柱模板' else ''
    
    report = f"""
# 模板工程设计计算书

## 1. 工程概况

| 项目 | 内容 |
|------|------|
| 模板类型 | {params['template_type']} |
| 混凝土厚度 | {params['concrete_thickness']} mm |
| 浇筑高度 | {params['pour_height']} m |
| 设计日期 | {today} |

## 2. 荷载计算

### 2.1 荷载标准值

| 荷载类型 | 数值 | 单位 |
|----------|------|------|
| 混凝土自重 | {loads['concrete_self']:.2f} | kN/m² |
| 施工荷载 | {loads['construction_load']:.2f} | kN/m² |
| 振捣荷载 | {loads['vibration_load']:.2f} | kN/m² |
{lateral_row}

### 2.2 设计荷载

q = γG × 混凝土自重 + γQ × (施工荷载 + 振捣荷载)

= {loads['total_load']:.2f} kN/m²

## 3. 面板验算

- 面板材料：{params['panel_material']}
- 计算跨度：{params['purlin_spacing']} mm
- 最大弯矩：{panel['M_max']:.2f} N·mm/mm
- 抗弯承载力：{panel_check['M_n']:.2f} N·mm/mm
- **利用率：{panel_check['util']:.1%}** {'✅ 通过' if panel_check['ok'] else '❌ 不通过'}

## 4. 木楞验算

- 木楞材料：{params['purlin_material']}
- 计算跨度：{params['support_spacing']} mm
- 最大弯矩：{purlin['M_max']:.2f} N·mm
- 抗弯承载力：{purlin_check['M_n']:.2f} N·mm
- **利用率：{purlin_check['util']:.1%}** {'✅ 通过' if purlin_check['ok'] else '❌ 不通过'}

## 5. 支撑验算

- 支撑高度：{params['support_height']} m
- 轴向压力：{support['N']:.2f} N
- 稳定承载力：{support_check['N_n']:.2f} N
- **利用率：{support_check['util']:.1%}** {'✅ 通过' if support_check['ok'] else '❌ 不通过'}

---

## 6. 设计结论

{'**所有构件验算通过。**' if (panel_check['ok'] and purlin_check['ok'] and support_check['ok']) else '**部分构件验算不通过，需调整参数。**'}

---
*本计算书由结构设计辅助系统自动生成*
"""
    return report

